require_once __DIR__.'/includes/db.php';require_once __DIR__.'/includes/upload_names.php';$pdo=db();$status=(string)($_GET['status']??'');$sql='SELECT * FROM competitions';$args=[];if(in_array($status,['upcoming','completed'],true)){$sql.=' WHERE status=?';$args[]=$status;}$sql.=' ORDER BY event_date DESC';$s=$pdo->prepare($sql);$s->execute($args);$rows=$s->fetchAll();$pageTitle='Соревнования';require __DIR__.'/includes/header.php';
?><section class="mx-auto max-w-7xl px-4 py-14"><p class="font-bold uppercase tracking-widest text-red-500">Календарь стартов</p><h1 class="mt-2 text-4xl font-black">Соревнования</h1><p class="mt-3 max-w-2xl text-gray-400">События и результаты спортсменов школы.</p><div class="my-8 flex flex-wrap gap-3"><?php foreach([''=>'Все','upcoming'=>'Предстоящие','completed'=>'Завершенные'] as $key=>$label):?><a class="rounded-lg px-4 py-2 <?=($status===$key?'bg-sport':'bg-neutral-800 hover:bg-neutral-700')?>" href="competitions.php<?=($key!==''?'?status='.h($key):'')?>"><?=h($label)?></a><?php endforeach;?></div><div class="overflow-x-auto rounded-2xl border border-white/10"><table class="w-full min-w-[760px] text-left text-sm"><thead class="bg-neutral-900 text-gray-400"><tr><th class="p-4">Дата</th><th class="p-4">Соревнование</th><th class="p-4">Место</th><th class="p-4">Возраст</th><th class="p-4">Статус / файлы</th></tr></thead><tbody><?php foreach($rows as $r):?><tr class="border-t border-white/10"><td class="p-4 font-bold text-red-400"><?=h(date('d.m.Y',strtotime($r['event_date'])))?></td><td class="p-4 font-semibold"><?=h($r['title'])?></td><td class="p-4 text-gray-300"><?=h($r['place'])?></td><td class="p-4 text-gray-300"><?=h($r['age_group'])?></td><td class="p-4"><span class="rounded-full px-3 py-1 text-xs <?=$r['status']==='completed'?'bg-gray-700':'bg-green-900 text-green-200'?>"><?=$r['status']==='completed'?'Завершено':'Предстоит'?></span><?php if($r['document']):?><a class="ml-3 text-red-400" href="<?=h(file_view_url($r['document']))?>" target="_blank">Документ</a><?php endif;?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5" class="p-8 text-center text-gray-400">Записей пока нет.</td></tr><?php endif;?></tbody></table></div></section><?php require __DIR__.'/includes/footer.php';
